import { pool } from "../db.js";

/**
 * The learner's standing on the teaching path: what they have demonstrated, what
 * they are on, and what is still locked.
 *
 * A DIFFERENT QUESTION FROM THE GAMES' ONE. curriculum/eligibility.ts asks what a
 * learner may be DEALT, from history they generated by playing. This asks what
 * they have WORKED THROUGH, from lessons they walked deliberately. The two
 * inform each other eventually; neither is the other's substitute.
 *
 * ORDER, NOT PREREQUISITES. Inside a topic the concepts are already sequenced,
 * and that sequence was authored to build -- `primitive-types` before `typeof`,
 * because typeof is a tool for inspecting a thing you must already know exists.
 * So "what am I learning now" is the first undemonstrated concept in that order,
 * and everything after it is locked. Running the prerequisite graph here would
 * answer "what could I reach", unlock four concepts at once, and hand the
 * beginner back the choice the journey exists to make for them.
 */

export type ConceptState = "demonstrated" | "current" | "locked";

export interface JourneyConcept {
    slug: string;
    name: string;
    /** Completes "I know how to ___". */
    objective: string;
    state: ConceptState;
    /** True when they came back to it after a wrong answer. */
    neededRetry: boolean;
}

export interface JourneyTopic {
    slug: string;
    name: string;
    /** The JavaScript idea the topic establishes. Empty until authored. */
    principle: string;
    order: number;
    /**
     * Complete needs BOTH: every concept demonstrated, and the topic challenge
     * passed. Walking the lessons alone leaves it `current`.
     */
    state: "complete" | "current" | "locked";
    concepts: JourneyConcept[];
    /**
     * The cumulative checkpoint. `state` is locked until every concept under the
     * topic is demonstrated, then current, then complete.
     *
     * null for the thirteen topics with no authored challenge yet -- those
     * complete on their concepts alone, so the journey does not dead-end at a
     * checkpoint nobody has written.
     */
    challenge: { state: ConceptState } | null;
}

interface Row {
    topic_slug: string;
    topic_name: string;
    principle: string;
    topic_order: number;
    concept_slug: string;
    concept_name: string;
    objective: string;
    demonstrated: boolean;
    needed_retry: boolean;
    challenge_done: boolean;
}

/** Topics that have an authored cumulative challenge. */
const CHALLENGED = new Set(["values", "variables", "operators"]);

/**
 * The whole journey, topic by topic and concept by concept.
 *
 * One query rather than one per topic: the shape is small -- 16 topics, 100
 * concepts -- and the page renders all of it, so paging would cost more than it
 * saved.
 */
export async function findJourneyPath(userId: string): Promise<JourneyTopic[]> {
    const result = await pool.query<Row>(
        `SELECT t.slug         AS topic_slug,
                t.name         AS topic_name,
                t.principle    AS principle,
                t.display_order AS topic_order,
                c.slug         AS concept_slug,
                c.name         AS concept_name,
                c.objective    AS objective,
                (d.user_id IS NOT NULL)            AS demonstrated,
                COALESCE(d.needed_retry, FALSE)    AS needed_retry,
                (tc.user_id IS NOT NULL)           AS challenge_done
         FROM topics t
         JOIN concepts c ON c.topic_id = t.id
         LEFT JOIN concept_demonstrations d
                ON d.concept_id = c.id AND d.user_id = $1
         LEFT JOIN topic_challenge_completions tc
                ON tc.topic_id = t.id AND tc.user_id = $1
         ORDER BY t.display_order, c.display_order`,
        [userId]
    );

    const topics: JourneyTopic[] = [];
    const byTopic = new Map<string, boolean>();

    for (const row of result.rows) {
        let topic = topics.at(-1);

        if (!topic || topic.slug !== row.topic_slug) {
            topic = {
                slug: row.topic_slug,
                name: row.topic_name,
                principle: row.principle,
                order: row.topic_order,
                state: "locked",
                concepts: [],
                challenge: CHALLENGED.has(row.topic_slug) ? { state: "locked" } : null
            };
            topics.push(topic);
            byTopic.set(row.topic_slug, row.challenge_done);
        }

        topic.concepts.push({
            slug: row.concept_slug,
            name: row.concept_name,
            objective: row.objective,
            state: row.demonstrated ? "demonstrated" : "locked",
            neededRetry: row.needed_retry
        });
    }

    // ONE ORDERED PATH, and the current step is the first unfinished thing on
    // it. Each topic contributes its concepts and then its challenge, so the
    // challenge sits between the last concept of one topic and the first of the
    // next -- which is what makes it a gate rather than an optional extra.
    //
    // Resolved in a second pass rather than inline, because "first unfinished"
    // is a property of the whole sequence and cannot be decided while it is
    // still being built.
    let positionTaken = false;

    for (const topic of topics) {
        for (const concept of topic.concepts) {
            if (concept.state === "demonstrated") continue;

            if (!positionTaken) {
                concept.state = "current";
                positionTaken = true;
            }
        }

        const conceptsDone = topic.concepts.every((c) => c.state === "demonstrated");
        const challengeDone = byTopic.get(topic.slug) === true;

        if (topic.challenge) {
            topic.challenge.state = challengeDone
                ? "demonstrated"
                : conceptsDone && !positionTaken
                  ? "current"
                  : "locked";

            if (topic.challenge.state === "current") {
                positionTaken = true;
            }
        }

        const finished = conceptsDone && (!topic.challenge || challengeDone);

        topic.state = finished
            ? "complete"
            : topic.concepts.some((c) => c.state === "current") ||
                topic.challenge?.state === "current"
              ? "current"
              : "locked";
    }

    return topics;
}

/**
 * Records that a learner worked through a concept's lesson.
 *
 * Idempotent by primary key: re-walking a lesson is allowed and changes nothing,
 * including `needed_retry` -- a learner who struggled the first time and breezed
 * through the second has still struggled once, and overwriting that would erase
 * the only evidence a remediation pass could ever use.
 *
 * Returns false when the slug names no concept, which the route turns into a 404
 * rather than silently accepting a demonstration of nothing.
 */
export async function recordDemonstration(
    userId: string,
    conceptSlug: string,
    neededRetry: boolean
): Promise<boolean> {
    const result = await pool.query(
        `INSERT INTO concept_demonstrations (user_id, concept_id, needed_retry)
         SELECT $1, c.id, $3 FROM concepts c WHERE c.slug = $2
         ON CONFLICT (user_id, concept_id) DO NOTHING`,
        [userId, conceptSlug, neededRetry]
    );

    if ((result.rowCount ?? 0) > 0) {
        return true;
    }

    // Either already demonstrated, or no such concept. Only the second is a 404.
    const exists = await pool.query(`SELECT 1 FROM concepts WHERE slug = $1`, [conceptSlug]);

    return (exists.rowCount ?? 0) > 0;
}

/**
 * Records that a learner passed a topic's cumulative challenge.
 *
 * Idempotent and non-overwriting, exactly like recordDemonstration: re-taking a
 * challenge is allowed, changes nothing, and does not erase the fact that the
 * first attempt needed a retry.
 */
export async function recordChallenge(
    userId: string,
    topicSlug: string,
    neededRetry: boolean
): Promise<boolean> {
    const result = await pool.query(
        `INSERT INTO topic_challenge_completions (user_id, topic_id, needed_retry)
         SELECT $1, t.id, $3 FROM topics t WHERE t.slug = $2
         ON CONFLICT (user_id, topic_id) DO NOTHING`,
        [userId, topicSlug, neededRetry]
    );

    if ((result.rowCount ?? 0) > 0) {
        return true;
    }

    const exists = await pool.query(`SELECT 1 FROM topics WHERE slug = $1`, [topicSlug]);

    return (exists.rowCount ?? 0) > 0;
}

/**
 * Points, derived rather than stored.
 *
 * WHY NO POINTS TABLE. A balance column would be a second source of truth for
 * something already recorded: concept_demonstrations and
 * topic_challenge_completions each hold one row per learner per thing, enforced
 * by a primary key. Counting them IS the balance, and it cannot drift from the
 * progress it represents.
 *
 * IT ALSO CANNOT BE FARMED, and that falls out of the same property rather than
 * needing a rule. Re-walking a lesson inserts nothing, so it pays nothing. There
 * is no action a learner can repeat for points; the only way the number moves is
 * by demonstrating something new.
 *
 * SEPARATE FROM XP, deliberately. XP measures games played and is spent nowhere;
 * this measures understanding demonstrated and is what personalisation will
 * eventually draw on. PERFECT_GAME_XP and every game's scoring are untouched.
 */
export const POINTS_PER_CONCEPT = 25;
export const POINTS_PER_CHALLENGE = 75;

export interface LearnerPoints {
    total: number;
    concepts: number;
    challenges: number;
}

export async function findLearnerPoints(userId: string): Promise<LearnerPoints> {
    const result = await pool.query<{ concepts: number; challenges: number }>(
        `SELECT
             (SELECT COUNT(*)::INT FROM concept_demonstrations WHERE user_id = $1) AS concepts,
             (SELECT COUNT(*)::INT FROM topic_challenge_completions WHERE user_id = $1) AS challenges`,
        [userId]
    );

    const { concepts, challenges } = result.rows[0]!;

    return {
        concepts,
        challenges,
        total: concepts * POINTS_PER_CONCEPT + challenges * POINTS_PER_CHALLENGE
    };
}
